using CSharpToJava.Core.Java;
using CSharpToJava.Core.TypeScript;

namespace CSharpToTypeScript.Tests;

/// <summary>
/// Task 15：接口与 implements 发射。
/// 断言修订说明（以 IR/发射器实测为准）：
/// - 方法名为 Java camelCase（既有约定，Task 10/11/13/14 实证）：bar，非 Bar；
/// - 接口属性在 IR 中为自动生成访问器方法对（getX()/setX(value)，IsAutoGenerated = true），
///   合并发射为 TS 属性声明：仅 getter → readonly X: number;；get+set → X: number;；
///   只写属性（仅 setter）保留 setter 方法 + 诊断注释；
/// - implements/extends 类型经 Java→TS 映射：框架接口（Comparable/AutoCloseable → object）
///   在 heritage 位置降级为全局类型 Object（`object` 关键字非法，tsc TS2552，TS 5.x/7.x
///   一致）；用户接口未命中类型表时原样发射，泛型实参逐段映射（IBase&lt;Integer&gt; →
///   IBase&lt;number&gt;）。
/// </summary>
public class TsInterfaceEmissionTests : TsConversionTestBase
{
    private static string EmitType(JavaTypeDeclaration type)
    {
        var table = new TsMemberMappingTable(null, null);
        var imports = new TsImportCollector();
        var emitter = new TypeScriptEmitter();
        return emitter.EmitType(type, table, imports);
    }

    [Fact]
    public void Interface_Declaration_Emits_Export_Interface()
    {
        var result = Convert("""
interface IFoo
{
    int Bar();
}
""");
        Assert.True(result.Success);
        Assert.Contains("export interface IFoo {", result.GeneratedCode);
        // 方法名 Java camelCase（bar，非计划原断言 Bar——既有约定，以实测为准）
        Assert.Contains("bar(): number;", result.GeneratedCode);
        AssertCompilesWithCompat(result.GeneratedCode);
    }

    [Fact]
    public void Class_Implements_Interface_Emits_Implements()
    {
        var result = Convert("""
interface IFoo
{
    int Bar();
}
class Foo : IFoo
{
    public int Bar() { return 1; }
}
""");
        Assert.True(result.Success);
        Assert.Contains("export class Foo implements IFoo", result.GeneratedCode);
        AssertCompilesWithCompat(result.GeneratedCode);
    }

    [Fact]
    public void Interface_With_Properties_Emits_Properties()
    {
        var result = Convert("""
interface IPoint
{
    int X { get; }
    int Y { get; }
}
""");
        Assert.True(result.Success);
        Assert.Contains("export interface IPoint", result.GeneratedCode);
        // 接口属性发射为 readonly X: number;（仅 getter → 只读属性）；Y 为独立断言，
        // 避免与 X 子串冗余（双审 Minor ③）
        Assert.Contains("readonly X: number;", result.GeneratedCode);
        Assert.Contains("readonly Y: number;", result.GeneratedCode);
        AssertCompilesWithCompat(result.GeneratedCode);
    }

    [Fact]
    public void Interface_Extends_Interface_Emits_Extends()
    {
        var result = Convert("""
interface IBase
{
    int A();
}
interface IDerived : IBase
{
    int B();
}
""");
        Assert.True(result.Success);
        Assert.Contains("export interface IDerived extends IBase", result.GeneratedCode);
        AssertCompilesWithCompat(result.GeneratedCode);
    }

    [Fact]
    public void Interface_Property_With_Getter_And_Setter_Emits_Non_Readonly()
    {
        var result = Convert("""
interface IPoint
{
    int X { get; set; }
}
""");
        Assert.True(result.Success);
        // get+set → 非只读属性（无 readonly 前缀）
        Assert.Contains("    X: number;", result.GeneratedCode);
        Assert.DoesNotContain("readonly X: number;", result.GeneratedCode);
        AssertCompilesWithCompat(result.GeneratedCode);
    }

    [Fact]
    public void Interface_Write_Only_Property_Keeps_Setter_With_Diagnostic()
    {
        var result = Convert("""
interface IWritable
{
    int Z { set; }
}
""");
        Assert.True(result.Success);
        // 只写属性（仅 setter）无 TS 对应形态：保留 setter 方法 + 诊断注释
        Assert.Contains("/* cs2j: write-only property Z: no TS counterpart; kept as setter method */", result.GeneratedCode);
        Assert.Contains("setZ(value: number): void;", result.GeneratedCode);
        AssertCompilesWithCompat(result.GeneratedCode);
    }

    [Fact]
    public void Class_Implements_Mapped_Framework_Interface_Emits_Object()
    {
        // Task 14 审查登记：implements Comparable<S> 不走 MapType 原样发射、非法 TS。
        // 本任务修复：heritage 类型经 Java→TS 映射；映射结果为 object 时降级为全局
        // 类型 Object（implements 位置 `object` 关键字非法，tsc TS2552）。
        var result = Convert("""
class Point : IComparable<Point>
{
    public int CompareTo(Point other) { return 0; }
}
class Auto : System.IDisposable
{
    public void Dispose() { }
}
""");
        Assert.True(result.Success);
        Assert.Contains("export class Point implements Object", result.GeneratedCode);
        Assert.Contains("export class Auto implements Object", result.GeneratedCode);
        AssertCompiles(result.GeneratedCode);
    }

    [Fact]
    public void Class_Implements_Generic_Interface_Emits_Mapped_Args()
    {
        var result = Convert("""
interface IRepo<T>
{
    T Find();
}
class Foo : IRepo<int>
{
    public int Find() { return 0; }
}
""");
        Assert.True(result.Success);
        // 用户接口未命中类型表：原样保留，泛型实参逐段映射（Integer → number）；
        // 单层实参全部命中 → 无嵌套泛型诊断注释
        Assert.Contains("export class Foo implements IRepo<number>", result.GeneratedCode);
        Assert.DoesNotContain("cs2j: unmapped nested generic args", result.GeneratedCode);
        AssertCompilesWithCompat(result.GeneratedCode);
    }

    [Fact]
    public void Interface_Extends_Generic_Interface_Emits_Mapped_Args()
    {
        var result = Convert("""
interface IBase<T>
{
    T A();
}
interface IDerived : IBase<int>
{
    int B();
}
""");
        Assert.True(result.Success);
        Assert.Contains("export interface IDerived extends IBase<number>", result.GeneratedCode);
        // 单层实参全部命中 → 无嵌套泛型诊断注释
        Assert.DoesNotContain("cs2j: unmapped nested generic args", result.GeneratedCode);
        AssertCompilesWithCompat(result.GeneratedCode);
    }

    [Fact]
    public void Interface_Extends_Nested_Generic_Args_Emits_Diagnostic_Comment()
    {
        // 组件级（IR 直构）：嵌套泛型实参（Pair<Integer, Integer>）按逗号切分无法完整映射，
        // 产物非法 TS（tsc TS2304）→ 回拼后追加诊断注释；完整修复（深度递归映射 + import
        // 收集）随命名管线任务登记（计划注记 ④）
        var iface = new JavaInterfaceDeclaration { Name = "IDerived", Modifiers = JavaModifiers.Public };
        iface.ExtendedTypes.Add("IBase<Pair<Integer, Integer>>");
        var result = EmitType(iface);
        Assert.Contains("extends IBase<Pair<Integer, Integer>> /* cs2j: unmapped nested generic args */", result);
        // L3：注释形态为合法 TS 语法（Integer 别名与 Pair/IBase 声明仅为探针提供解析，
        // 发射文本原样保留，含注释行）
        AssertCompiles("type Integer = number;\n" +
            "interface Pair<A, B> { a: A; b: B; }\n" +
            "interface IBase<T> { a: T; }\n" +
            result);
    }

    [Fact]
    public void Accessor_Like_User_Methods_Are_Not_Merged()
    {
        // 边界：get/set 前缀形态但非属性访问器的方法保持方法发射——GetURL()
        // （IsAutoGenerated = false 不合并）、get()（长度 ≤ 3，且 get 为 TS 保留字
        // → SafeIdentifier 转义为 get$）、GetItem(int)（带参）
        var result = Convert("""
interface IEdge
{
    string GetURL();
    int get();
    int GetItem(int index);
}
""");
        Assert.True(result.Success);
        Assert.Contains("getURL(): string;", result.GeneratedCode);
        Assert.Contains("get$(): number;", result.GeneratedCode);
        Assert.Contains("getItem(index: number): number;", result.GeneratedCode);
        AssertCompilesWithCompat(result.GeneratedCode);
    }

    [Fact]
    public void Parameterized_Auto_Generated_Accessor_Is_Not_Merged()
    {
        // 组件级：自动生成但带参数的访问器（索引器形态 getItem(index)）不可能合并为
        // TS 属性（属性声明无参数），IsAccessor 参数守卫保持方法形态
        var iface = new JavaInterfaceDeclaration { Name = "IList", Modifiers = JavaModifiers.Public };
        var getItem = new JavaMethodDeclaration
        {
            Name = "getItem",
            ReturnType = "int",
            IsAutoGenerated = true,
        };
        getItem.Parameters.Add(new JavaParameter("int", "index"));
        iface.Methods.Add(getItem);
        var result = EmitType(iface);
        Assert.Contains("getItem(index: number): number;", result);
        Assert.DoesNotContain("readonly Item: number;", result);
        AssertCompiles(result);
    }
}
